  6023  /**
  6024   * g_variant_get_normal_form:
  6025   * @value: a #GVariant
  6026   *
  6027   * Gets a #GVariant instance that has the same value as @value and is
  6028   * trusted to be in normal form.
  6029   *
  6030   * If @value is already trusted to be in normal form then a new
  6031   * reference to @value is returned.
  6032   *
  6033   * If @value is not already trusted, then it is scanned to check if it
  6034   * is in normal form.  If it is found to be in normal form then it is
  6035   * marked as trusted and a new reference to it is returned.
  6036   *
  6037   * If @value is found not to be in normal form then a new trusted
  6038   * #GVariant is created with the same value as @value. The non-normal parts of
  6039   * @value will be replaced with default values which are guaranteed to be in
  6040   * normal form.
  6041   *
  6042   * It makes sense to call this function if you've received #GVariant
  6043   * data from untrusted sources and you want to ensure your serialized
  6044   * output is definitely in normal form.
  6045   *
  6046   * If @value is already in normal form, a new reference will be returned
  6047   * (which will be floating if @value is floating). If it is not in normal form,
  6048   * the newly created #GVariant will be returned with a single non-floating
  6049   * reference. Typically, g_variant_take_ref() should be called on the return
  6050   * value from this function to guarantee ownership of a single non-floating
  6051   * reference to it.
  6052   *
  6053   * Returns: (transfer full): a trusted #GVariant
  6054   *
  6055   * Since: 2.24
  6056   **/
  6057  GVariant *
  6058  g_variant_get_normal_form (GVariant *value)
  6059  {
  6060    GVariant *trusted;
  6061
  6062    if (g_variant_is_normal_form (value))
  6063      return g_variant_ref (value);
  6064
  6065    trusted = g_variant_deep_copy (value, FALSE);
  6066    g_assert (g_variant_is_trusted (trusted));
  6067
  6068    return g_variant_ref_sink (trusted);
  6069  }
