   474    g_variant_type_info_query (child.type_info, NULL, &child.size);
   475    child.data = value.data + (child.size * index_);
   476    g_variant_type_info_ref (child.type_info);
   477    child.depth = value.depth + 1;
   478
   479    return child;
   480  }
   481
   482  static gsize
   483  gvs_fixed_sized_array_needed_size (GVariantTypeInfo         *type_info,
   484                                     GVariantSerialisedFiller  gvs_filler,
   485                                     const gpointer           *children,
   486                                     gsize                     n_children)
   487  {
   488    gsize element_fixed_size;
   489
   490    g_variant_type_info_query_element (type_info, NULL, &element_fixed_size);
   491
   492    return element_fixed_size * n_children;
   493  }
   494
   495  static void
   496  gvs_fixed_sized_array_serialise (GVariantSerialised        value,
   497                                   GVariantSerialisedFiller  gvs_filler,
   498                                   const gpointer           *children,
   499                                   gsize                     n_children)
   500  {
   501    GVariantSerialised child = { 0, };
   502    gsize i;
   503
   504    child.type_info = g_variant_type_info_element (value.type_info);
   505    g_variant_type_info_query (child.type_info, NULL, &child.size);
   506    child.data = value.data;
   507    child.depth = value.depth + 1;
   508
   509    for (i = 0; i < n_children; i++)
   510      {
   511        gvs_filler (&child, children[i]);
   512        child.data += child.size;
   513      }
   514  }
   515
   516  static gboolean
   517  gvs_fixed_sized_array_is_normal (GVariantSerialised value)
   518  {
   519    GVariantSerialised child = { 0, };
   520
   521    child.type_info = g_variant_type_info_element (value.type_info);
   522    g_variant_type_info_query (child.type_info, NULL, &child.size);
   523    child.depth = value.depth + 1;
   524
   525    if (value.size % child.size != 0)
   526      return FALSE;
   527
   528    for (child.data = value.data;
   529         child.data < value.data + value.size;
   530         child.data += child.size)
   531      {
   532        if (!g_variant_serialised_is_normal (child))
   533          return FALSE;
   534      }
   535
   536    return TRUE;
   537  }
   538
   539  /* Variable-sized Array {{{3
   540   *
   541   * Variable sized arrays, containing variable-sized elements, must be
   542   * able to determine the boundaries between the elements.  The items
   543   * cannot simply be concatenated.  Additionally, we are faced with the
   544   * fact that non-fixed-sized values do not necessarily have a size that
   545   * is a multiple of their alignment requirement, so we may need to
   546   * insert zero-filled padding.
   547   *
   548   * While it is possible to find the start of an item by starting from
   549   * the end of the item before it and padding for alignment, it is not
   550   * generally possible to do the reverse operation.  For this reason, we
   551   * record the end point of each element in the array.
   552   *
   553   * GVariant works in terms of "offsets".  An offset is a pointer to a
   554   * boundary between two bytes.  In 4 bytes of serialized data, there
   555   * would be 5 possible offsets: one at the start ('0'), one between each
   556   * pair of adjacent bytes ('1', '2', '3') and one at the end ('4').
   557   *
   558   * The numeric value of an offset is an unsigned integer given relative
   559   * to the start of the serialized data of the array.  Offsets are always
   560   * stored in little endian byte order and are always only as big as they
   561   * need to be.  For example, in 255 bytes of serialized data, there are
   562   * 256 offsets.  All possibilities can be stored in an 8 bit unsigned
   563   * integer.  In 256 bytes of serialized data, however, there are 257
   564   * possible offsets so 16 bit integers must be used.  The size of an
   565   * offset is always a power of 2.
   566   *
   567   * The offsets are stored at the end of the serialized data of the
   568   * array.  They are simply concatenated on without any particular
   569   * alignment.  The size of the offsets is included in the size of the
   570   * serialized data for purposes of determining the size of the offsets.
   571   * This presents a possibly ambiguity; in certain cases, a particular
   572   * value of array could have two different serialized forms.
   573   *
   574   * Imagine an array containing a single string of 253 bytes in length
   575   * (so, 254 bytes including the nul terminator).  Now the offset must be
   576   * written.  If an 8 bit offset is written, it will bring the size of
   577   * the array's serialized data to 255 -- which means that the use of an
   578   * 8 bit offset was valid.  If a 16 bit offset is used then the total
   579   * size of the array will be 256 -- which means that the use of a 16 bit
   580   * offset was valid.  Although both of these will be accepted by the
   581   * deserializer, only the smaller of the two is considered to be in
   582   * normal form and that is the one that the serializer must produce.
   583   */
   584
   585  /* bytes may be NULL if (size == 0). */
   586  static inline gsize
   587  gvs_read_unaligned_le (guchar *bytes,
   588                         guint   size)
   589  {
   590    union
   591    {
   592      guchar bytes[GLIB_SIZEOF_SIZE_T];
   593      gsize integer;
   594    } tmpvalue;
   595
   596    tmpvalue.integer = 0;
   597    if (bytes != NULL)
   598      memcpy (&tmpvalue.bytes, bytes, size);
   599
   600    return GSIZE_FROM_LE (tmpvalue.integer);
   601  }
   602
   603  static inline void
   604  gvs_write_unaligned_le (guchar *bytes,
   605                          gsize   value,
   606                          guint   size)
   607  {
   608    union
   609    {
   610      guchar bytes[GLIB_SIZEOF_SIZE_T];
   611      gsize integer;
   612    } tmpvalue;
   613
   614    tmpvalue.integer = GSIZE_TO_LE (value);
   615    memcpy (bytes, &tmpvalue.bytes, size);
   616  }
   617
   618  static guint
   619  gvs_get_offset_size (gsize size)
   620  {
   621    if (size > G_MAXUINT32)
   622      return 8;
   623
   624    else if (size > G_MAXUINT16)
   625      return 4;
   626
   627    else if (size > G_MAXUINT8)
   628      return 2;
   629
   630    else if (size > 0)
   631      return 1;
   632
   633    return 0;
   634  }
   635
   636  static gsize
   637  gvs_calculate_total_size (gsize body_size,
   638                            gsize offsets)
   639  {
   640    if (body_size + 1 * offsets <= G_MAXUINT8)
   641      return body_size + 1 * offsets;
   642
   643    if (body_size + 2 * offsets <= G_MAXUINT16)
   644      return body_size + 2 * offsets;
   645
   646    if (body_size + 4 * offsets <= G_MAXUINT32)
   647      return body_size + 4 * offsets;
   648
   649    return body_size + 8 * offsets;
   650  }
   651
   652  struct Offsets
   653  {
   654    gsize     data_size;
   655
   656    guchar   *array;
   657    gsize     length;
   658    guint     offset_size;
   659
   660    gboolean  is_normal;
   661  };
   662
   663  static gsize
   664  gvs_offsets_get_offset_n (struct Offsets *offsets,
   665                            gsize           n)
   666  {
   667    return gvs_read_unaligned_le (
   668        offsets->array + (offsets->offset_size * n), offsets->offset_size);
   669  }
   670
   671  static struct Offsets
   672  gvs_variable_sized_array_get_frame_offsets (GVariantSerialised value)
   673  {
   674    struct Offsets out = { 0, };
   675    gsize offsets_array_size;
   676    gsize last_end;
   677
   678    if (value.size == 0)
   679      {
   680        out.is_normal = TRUE;
   681        return out;
   682      }
   683
   684    out.offset_size = gvs_get_offset_size (value.size);
   685    last_end = gvs_read_unaligned_le (value.data + value.size - out.offset_size,
   686                                      out.offset_size);
   687
   688    if (last_end > value.size)
   689      return out;  /* offsets not normal */
   690
   691    offsets_array_size = value.size - last_end;
   692
   693    if (offsets_array_size % out.offset_size)
   694      return out;  /* offsets not normal */
   695
   696    out.data_size = last_end;
   697    out.array = value.data + last_end;
   698    out.length = offsets_array_size / out.offset_size;
   699
   700    if (out.length > 0 && gvs_calculate_total_size (last_end, out.length) != value.size)
   700    if (out.length > 0 && gvs_calculate_total_size (last_end, out.length) != value.size)
   701      return out;  /* offset size not minimal */
   702
   703    out.is_normal = TRUE;
   704
   705    return out;
   706  }
   707
   708  static gsize
   709  gvs_variable_sized_array_n_children (GVariantSerialised value)
   710  {
   711    return gvs_variable_sized_array_get_frame_offsets (value).length;
   712  }
   713
   714  /* Find the index of the first out-of-order element in @data, assuming that
   715   * @data is an array of elements of given @type, starting at index @start and
   716   * containing a further @len-@start elements. */
   717  #define DEFINE_FIND_UNORDERED(type) \
   718    static gsize \
   719    find_unordered_##type (const guint8 *data, gsize start, gsize len) \
   720    { \
   721      gsize off; \
   722      type current, previous; \
   723      \
   724      memcpy (&previous, data + start * sizeof (current), sizeof (current)); \
   725      for (off = (start + 1) * sizeof (current); off < len * sizeof (current); off += sizeof (current)) \
   726        { \
   727          memcpy (&current, data + off, sizeof (current)); \
   728          if (current < previous) \
   729            break; \
   730          previous = current; \
   731        } \
   732      return off / sizeof (current) - 1; \
   733    }
   734
   735  DEFINE_FIND_UNORDERED (guint8);
   736  DEFINE_FIND_UNORDERED (guint16);
   737  DEFINE_FIND_UNORDERED (guint32);
   738  DEFINE_FIND_UNORDERED (guint64);
   739
   740  static GVariantSerialised
   741  gvs_variable_sized_array_get_child (GVariantSerialised value,
   742                                      gsize              index_)
   743  {
   744    GVariantSerialised child = { 0, };
   745
   746    struct Offsets offsets = gvs_variable_sized_array_get_frame_offsets (value);
   747
   748    gsize start;
   749    gsize end;
   750
   751    child.type_info = g_variant_type_info_element (value.type_info);
   752    g_variant_type_info_ref (child.type_info);
   753    child.depth = value.depth + 1;
   754
   755    /* If the requested @index_ is beyond the set of indices whose framing offsets
   756     * have been checked, check the remaining offsets to see whether they’re
   757     * normal (in order, no overlapping array elements).
   758     *
   759     * Don’t bother checking if the highest known-good offset is lower than the
   760     * highest checked offset, as that means there’s an invalid element at that
   761     * index, so there’s no need to check further. */
   762    if (index_ > value.checked_offsets_up_to &&
   763        value.ordered_offsets_up_to == value.checked_offsets_up_to)
   764      {
   765        switch (offsets.offset_size)
   766          {
   767          case 1:
   768            {
   769              value.ordered_offsets_up_to = find_unordered_guint8 (
   770                  offsets.array, value.checked_offsets_up_to, index_ + 1);
   771              break;
   772            }
   773          case 2:
   774            {
   775              value.ordered_offsets_up_to = find_unordered_guint16 (
   776                  offsets.array, value.checked_offsets_up_to, index_ + 1);
   777              break;
   778            }
   779          case 4:
   780            {
   781              value.ordered_offsets_up_to = find_unordered_guint32 (
   782                  offsets.array, value.checked_offsets_up_to, index_ + 1);
   783              break;
   784            }
   785          case 8:
   786            {
   787              value.ordered_offsets_up_to = find_unordered_guint64 (
   788                  offsets.array, value.checked_offsets_up_to, index_ + 1);
   789              break;
   790            }
   791          default:
   792            /* gvs_get_offset_size() only returns maximum 8 */
   793            g_assert_not_reached ();
   794          }
   795
   796        value.checked_offsets_up_to = index_;
   797      }
   798
   799    if (index_ > value.ordered_offsets_up_to)
   800      {
   801        /* Offsets are invalid somewhere, so return an empty child. */
   802        return child;
   803      }
   804
   805    if (index_ > 0)
   806      {
   807        guint alignment;
   808
   809        start = gvs_offsets_get_offset_n (&offsets, index_ - 1);
   810
   811        g_variant_type_info_query (child.type_info, &alignment, NULL);
   812        start += (-start) & alignment;
   813      }
   814    else
   815      start = 0;
   816
   817    end = gvs_offsets_get_offset_n (&offsets, index_);
   818
   819    if (start < end && end <= value.size && end <= offsets.data_size)
   820      {
   821        child.data = value.data + start;
   822        child.size = end - start;
   823      }
   824
   825    return child;
   826  }
   827
   828  static gsize
   829  gvs_variable_sized_array_needed_size (GVariantTypeInfo         *type_info,
   830                                        GVariantSerialisedFiller  gvs_filler,
   831                                        const gpointer           *children,
   832                                        gsize                     n_children)
   833  {
   834    guint alignment;
   835    gsize offset;
   836    gsize i;
   837
   838    g_variant_type_info_query (type_info, &alignment, NULL);
   839    offset = 0;
   840
   841    for (i = 0; i < n_children; i++)
   842      {
   843        GVariantSerialised child = { 0, };
   844
   845        offset += (-offset) & alignment;
   846        gvs_filler (&child, children[i]);
   847        offset += child.size;
   848      }
   849
   850    return gvs_calculate_total_size (offset, n_children);
   851  }
   852
   853  static void
   854  gvs_variable_sized_array_serialise (GVariantSerialised        value,
   855                                      GVariantSerialisedFiller  gvs_filler,
   856                                      const gpointer           *children,
   857                                      gsize                     n_children)
   858  {
   859    guchar *offset_ptr;
   860    gsize offset_size;
   861    guint alignment;
   862    gsize offset;
   863    gsize i;
   864
   865    g_variant_type_info_query (value.type_info, &alignment, NULL);
   866    offset_size = gvs_get_offset_size (value.size);
   867    offset = 0;
   868
   869    offset_ptr = value.data + value.size - offset_size * n_children;
   870
   871    for (i = 0; i < n_children; i++)
   872      {
   873        GVariantSerialised child = { 0, };
   874
   875        while (offset & alignment)
   876          value.data[offset++] = '\0';
   877
   878        child.data = value.data + offset;
   879        gvs_filler (&child, children[i]);
   880        offset += child.size;
   881
   882        gvs_write_unaligned_le (offset_ptr, offset, offset_size);
   883        offset_ptr += offset_size;
   884      }
   885  }
   886
   887  static gboolean
   888  gvs_variable_sized_array_is_normal (GVariantSerialised value)
   889  {
   890    GVariantSerialised child = { 0, };
   891    guint alignment;
   892    gsize offset;
   893    gsize i;
   894
   895    struct Offsets offsets = gvs_variable_sized_array_get_frame_offsets (value);
   896
   897    if (!offsets.is_normal)
   898      return FALSE;
   899
   900    if (value.size != 0 && offsets.length == 0)
   901      return FALSE;
   902
   903    child.type_info = g_variant_type_info_element (value.type_info);
   904    g_variant_type_info_query (child.type_info, &alignment, NULL);
   905    child.depth = value.depth + 1;
   906    offset = 0;
   907
   908    for (i = 0; i < offsets.length; i++)
   909      {
   910        gsize this_end;
   911
   912        this_end = gvs_read_unaligned_le (offsets.array + offsets.offset_size * i,
   913                                          offsets.offset_size);
   914
   915        if (this_end < offset || this_end > offsets.data_size)
   916          return FALSE;
   917
   918        while (offset & alignment)
   919          {
   920            if (!(offset < this_end && value.data[offset] == '\0'))
   921              return FALSE;
   922            offset++;
   923          }
   924
   925        child.data = value.data + offset;
   926        child.size = this_end - offset;
   927
   928        if (child.size == 0)
   929          child.data = NULL;
   930
   931        if (!g_variant_serialised_is_normal (child))
   932          return FALSE;
   933
   934        offset = this_end;
   935      }
   936
   937    g_assert (offset == offsets.data_size);
   938
   939    /* All offsets have now been checked. */
   940    value.ordered_offsets_up_to = G_MAXSIZE;
   941    value.checked_offsets_up_to = G_MAXSIZE;
   942
   943    return TRUE;
   944  }
   945
   946  /* Tuples {{{2
   947   *
   948   * Since tuples can contain a mix of variable- and fixed-sized items,
   949   * they are, in terms of serialization, a hybrid of variable-sized and
   950   * fixed-sized arrays.
   951   *
   952   * Offsets are only stored for variable-sized items.  Also, since the
   953   * number of items in a tuple is known from its type, we are able to
   954   * know exactly how many offsets to expect in the serialized data (and
   955   * therefore how much space is taken up by the offset array).  This
   956   * means that we know where the end of the serialized data for the last
   957   * item is -- we can just subtract the size of the offset array from the
   958   * total size of the tuple.  For this reason, the last item in the tuple
   959   * doesn't need an offset stored.
   960   *
   961   * Tuple offsets are stored in reverse.  This design choice allows
   962   * iterator-based deserializers to be more efficient.
   963   *
   964   * Most of the "heavy lifting" here is handled by the GVariantTypeInfo
   965   * for the tuple.  See the notes in gvarianttypeinfo.h.
   966   */
   967
   968  /* Note: This doesn’t guarantee that @out_member_end >= @out_member_start; that
   969   * condition may not hold true for invalid serialised variants. The caller is
   970   * responsible for checking the returned values and handling invalid ones
   971   * appropriately. */
   972  static void
   973  gvs_tuple_get_member_bounds (GVariantSerialised  value,
   974                               gsize               index_,
   975                               gsize               offset_size,
   976                               gsize              *out_member_start,
   977                               gsize              *out_member_end)
   978  {
   979    const GVariantMemberInfo *member_info;
   980    gsize member_start, member_end;
   981
   982    member_info = g_variant_type_info_member_info (value.type_info, index_);
   983
   984    if (member_info->i + 1)
   985      member_start = gvs_read_unaligned_le (value.data + value.size -
   986                                            offset_size * (member_info->i + 1),
   987                                            offset_size);
   988    else
   989      member_start = 0;
   990
   991    member_start += member_info->a;
   992    member_start &= member_info->b;
   993    member_start |= member_info->c;
   994
   995    if (member_info->ending_type == G_VARIANT_MEMBER_ENDING_LAST)
   996      member_end = value.size - offset_size * (member_info->i + 1);
   997
   998    else if (member_info->ending_type == G_VARIANT_MEMBER_ENDING_FIXED)
   999      {
  1000        gsize fixed_size;
  1001
  1002        g_variant_type_info_query (member_info->type_info, NULL, &fixed_size);
  1003        member_end = member_start + fixed_size;
  1004      }
  1005
  1006    else /* G_VARIANT_MEMBER_ENDING_OFFSET */
  1007      member_end = gvs_read_unaligned_le (value.data + value.size -
  1008                                          offset_size * (member_info->i + 2),
  1009                                          offset_size);
  1010
  1011    if (out_member_start != NULL)
  1012      *out_member_start = member_start;
  1013    if (out_member_end != NULL)
  1014      *out_member_end = member_end;
  1015  }
  1016
  1017  static gsize
  1018  gvs_tuple_n_children (GVariantSerialised value)
  1019  {
  1020    return g_variant_type_info_n_members (value.type_info);
  1310              while (offset & alignment)
  1311                if (value.data[offset++] != '\0')
  1312                  return FALSE;
  1313            }
  1314
  1315          g_assert (offset == value.size);
  1316        }
  1317    }
  1318
  1319    /* @offset_ptr has been counting backwards from the end of the variant, to
  1320     * find the beginning of the offset table. @offset has been counting forwards
  1321     * from the beginning of the variant to find the end of the data. They should
  1322     * have met in the middle. */
  1323    if (offset_ptr != offset)
  1324      return FALSE;
  1325
  1326    offset_table_size = value.size - offset_ptr;
  1327    if (value.size > 0 &&
  1328        gvs_calculate_total_size (offset, offset_table_size / offset_size) != value.size)
  1329      return FALSE;  /* offset size not minimal */
  1330
  1331    return TRUE;
  1332  }
